      "content": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Campus Queue</title>\n<link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n<main>\n  <h1>Campus Queue</h1>\n  <p>Pick a counter, join the queue, watch your place in line.</p>\n  <label>Counter\n    <select id=\"counter\"></select>\n  </label>\n  <label>Your name\n    <input id=\"name\" type=\"text\" placeholder=\"e.g. Ananya\">\n  </label>\n  <button id=\"join\">Join the queue</button>\n  <p id=\"status\"></p>\n  <ol id=\"board\"></ol>\n  <button id=\"refresh\">Refresh board</button>\n</main>\n<script src=\"app.js\"></script>\n</body>\n</html>\n"
