      "content": "body { font-family: system-ui, sans-serif; margin: 0; background: #f8fafc; color: #0f172a; }\nmain { max-width: 560px; margin: 48px auto; padding: 0 20px; }\nh1 { font-size: 28px; margin-bottom: 4px; }\nlabel { display: block; margin: 14px 0; font-weight: 600; }\ninput, select { display: block; width: 100%; margin-top: 6px; padding: 10px; font: inherit; border: 1px solid #cbd5e1; border-radius: 8px; }\nbutton { padding: 10px 16px; font: inherit; font-weight: 600; background: #1d4ed8; color: #fff; border: 0; border-radius: 8px; cursor: pointer; }\nol { padding-left: 20px; line-height: 1.8; }\n"
