    {
      "path": "server.js",
      "content": "const express = require(\"express\");\nconst path = require(\"path\");\nconst { createQueue, join, position, callNext, markDone, leave } = require(\"./src/queue\");\n\nconst app = express();\napp.use(express.json());\napp.use(express.static(path.join(__dirname, \"public\")));\n\nconst counters = {\n  \"main-canteen\": createQueue(\"Main Canteen\"),\n  \"juice-corner\": createQueue(\"Juice Corner\"),\n};\n\napp.get(\"/api/counters\", (req, res) => {\n  res.json(Object.keys(counters).map((id) => ({ id, name: counters[id].counter, waiting: counters[id].tokens.filter((t) => t.status === \"waiting\").length })));\n});\n\napp.get(\"/api/counters/:id\", (req, res) => {\n  const queue = counters[req.params.id];\n  if (!queue) return res.status(404).json({ error: \"unknown counter\" });\n  res.json({ counter: queue.counter, tokens: queue.tokens });\n});\n\napp.post(\"/api/counters/:id/join\", (req, res) => {\n  const queue = counters[req.params.id];\n  if (!queue) return res.status(404).json({ error: \"unknown counter\" });\n  try {\n    const token = join(queue, req.body.name);\n    res.status(201).json({ token, position: position(queue, token.id) });\n  } catch (err) {\n    res.status(400).json({ error: err.message });\n  }\n});\n\napp.post(\"/api/counters/:id/next\", (req, res) => {\n  const queue = counters[req.params.id];\n  if (!queue) return res.status(404).json({ error: \"unknown counter\" });\n  const token = callNext(queue);\n  if (!token) return res.status(409).json({ error: \"queue is empty\" });\n  res.json({ token });\n});\n\napp.post(\"/api/counters/:id/done/:tokenId\", (req, res) => {\n  const queue = counters[req.params.id];\n  if (!queue) return res.status(404).json({ error: \"unknown counter\" });\n  const token = markDone(queue, Number(req.params.tokenId));\n  if (!token) return res.status(404).json({ error: \"unknown token\" });\n  res.json({ token });\n});\n\napp.post(\"/api/counters/:id/leave/:tokenId\", (req, res) => {\n  const queue = counters[req.params.id];\n  if (!queue) return res.status(404).json({ error: \"unknown counter\" });\n  if (!leave(queue, Number(req.params.tokenId))) return res.status(404).json({ error: \"unknown token\" });\n  res.json({ ok: true });\n});\n\nconst PORT = process.env.PORT || 3000;\nif (require.main === module) {\n  app.listen(PORT, () => console.log(`Campus Queue listening on ${PORT}`));\n}\nmodule.exports = app;\n"
    },
    {
      "path": "src/queue.js",
      "content": "// Campus Queue — in-memory queue logic. No database: state resets on restart.\n// A queue is a list of tokens: { id, name, joinedAt, status }.\n// status is \"waiting\", \"called\" or \"done\".\nfunction createQueue(counterName) {\n  return { counter: counterName, tokens: [], nextNumber: 1 };\n}\n\nfunction join(queue, name) {\n  if (!name || !name.trim()) throw new Error(\"name is required\");\n  const token = { id: queue.nextNumber, name: name.trim(), joinedAt: new Date().toISOString(), status: \"waiting\" };\n  queue.nextNumber += 1;\n  queue.tokens.push(token);\n  return token;\n}\n\nfunction position(queue, tokenId) {\n  const waiting = queue.tokens.filter((t) => t.status === \"waiting\");\n  const index = waiting.findIndex((t) => t.id === tokenId);\n  return index === -1 ? null : index + 1;\n}\n\nfunction callNext(queue) {\n  const next = queue.tokens.find((t) => t.status === \"waiting\");\n  if (!next) return null;\n  next.status = \"called\";\n  return next;\n}\n\nfunction markDone(queue, tokenId) {\n  const token = queue.tokens.find((t) => t.id === tokenId);\n  if (!token) return null;\n  token.status = \"done\";\n  return token;\n}\n\nfunction leave(queue, tokenId) {\n  const before = queue.tokens.length;\n  queue.tokens = queue.tokens.filter((t) => t.id !== tokenId);\n  return queue.tokens.length < before;\n}\n\nmodule.exports = { createQueue, join, position, callNext, markDone, leave };\n"
    },
    {
      "path": "test/queue.test.js",
      "content": "const test = require(\"node:test\");\nconst assert = require(\"node:assert/strict\");\nconst { createQueue, join, position, callNext, markDone, leave } = require(\"../src/queue\");\n\ntest(\"join hands out tokens in order\", () => {\n  const q = createQueue(\"Main Canteen\");\n  const a = join(q, \"Ananya\");\n  const b = join(q, \"Rahul\");\n  assert.equal(a.id, 1);\n  assert.equal(b.id, 2);\n  assert.equal(position(q, b.id), 2);\n});\n\ntest(\"callNext picks the earliest waiting token\", () => {\n  const q = createQueue(\"Main Canteen\");\n  join(q, \"Ananya\");\n  join(q, \"Rahul\");\n  assert.equal(callNext(q).name, \"Ananya\");\n  assert.equal(position(q, 2), 1);\n});\n\ntest(\"leave removes a token and done marks it\", () => {\n  const q = createQueue(\"Juice Corner\");\n  const a = join(q, \"Meera\");\n  assert.equal(leave(q, a.id), true);\n  assert.equal(position(q, a.id), null);\n  const b = join(q, \"Kiran\");\n  assert.equal(markDone(q, b.id).status, \"done\");\n});\n\ntest(\"join rejects a blank name\", () => {\n  const q = createQueue(\"Main Canteen\");\n  assert.throws(() => join(q, \"   \"), /name is required/);\n});\n"
    }
